public class Main {
    static void run(int limit) {
        outer:
        for (int i = 0; i < limit; i++) {
            for (int j = 0; j < 3; j++) {
                if (j == 1) {
                    continue outer;
                }
                System.out.print(i + "" + j + " ");
            }
        }
    }
    public static void main(String[] args) {
        run(3);
    }
